actions.new:
// Mantener la sesión ante 500/502, pero propagar el error real.
// Nunca fabricar una respuesta vacía: eso convierte fallas de backend
// en falsos "0 registros" y rompe los fallbacks de los consumidores.
if (status === 500 || status === 502) {
  console.warn(
    "[API] Fallo de backend/red (500/502), manteniendo sesión y propagando error..."
  );
  return Promise.reject(error);
}

actions.old:
// Parche de estabilidad: Evitar cierre de sesión por errores 500/502.
// No debe convertir reportes en arreglos vacíos: eso oculta fallas reales
// como "Reporte generado: 0 registros" cuando el backend devolvió error.
if (status === 500 || status === 502) {
  console.warn("[API] Fallo de red detectado (500/502), manteniendo sesión...");
  if (url.includes('/reports/')) {
    return Promise.reject(error);
  }
  return Promise.resolve({ data: [] });
}

actions.new:
const [apiConnections, setApiConnections] = useState([]);
const [loadingApis, setLoadingApis] = useState(false);
const [apiLoadError, setApiLoadError] = useState(null);

const loadApiConnections = async () => {
  setLoadingApis(true);
  setApiLoadError(null);
  try {
    const response = await api.get('/api-connections');

    if (!response.data?.success || !Array.isArray(response.data?.data)) {
      throw new Error('Respuesta inválida del endpoint de conexiones API');
    }

    setApiConnections(response.data.data);
  } catch (error) {
    console.error('Error cargando conexiones API:', error);

    const detail =
      error.response?.data?.detail ||
      error.message ||
      'Error al cargar conexiones API';

    // Conservar datos previos. Un error no equivale a "0 conexiones".
    setApiLoadError(
      typeof detail === 'string'
        ? detail
        : 'Error al cargar conexiones API'
    );

    toast.error('No se pudieron cargar las conexiones API locales.');
  } finally {
    setLoadingApis(false);
  }
};

actions.old:
const loadApiConnections = async () => {
  setLoadingApis(true);
  try {
    const response = await api.get('/api-connections');
    if (response.data.success) {
      setApiConnections(response.data.data || []);
    }
  } catch (error) {
    console.error('Error cargando conexiones API:', error);
    // SECURITY P0: sin fallback hardcodeado. No inventar conexiones ni exponer IPs reales.
    setApiConnections([]);
    toast.error('No se pudieron cargar las conexiones API locales.');
  } finally {
    setLoadingApis(false);
  }
};

